// ===== Builtin class support =====
// Tag bit position for builtin object IDs (assumes 64-bit PHP)
const _BUILTIN_TAG_BIT = 60;

// Builtin object state (global variable - accessed via `global $_builtin_state;` in functions)
$_builtin_state = [
    'objects' => [],
    'objectMap' => [],
    'idCounter' => 0,
    'classNames' => [],      // builtin object ID -> class name
    'parentClasses' => [],   // class name -> array of parent class names
];

/**
 * Register an object and return its builtin object ID if it's an object.
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_register_if_object($result)
{
    global $_builtin_state;

    if (!is_object($result)) goto return_result;

    $oid = spl_object_id($result);

    if (!isset($_builtin_state['objectMap'][$oid])) goto create_new_id;

    $result = $_builtin_state['objectMap'][$oid];
    goto return_result;

    create_new_id:
    $_builtin_state['idCounter']++;
    $newId = $_builtin_state['idCounter'] | (1 << _BUILTIN_TAG_BIT);
    $_builtin_state['objects'][$newId] = $result;
    $_builtin_state['objectMap'][$oid] = $newId;

    // Store class name for instanceof checks
    $className = get_class($result); // @phpstan-ignore spaghetti.noTypeCheckFunction
    $_builtin_state['classNames'][$newId] = $className;

    // Store parent classes and interfaces if not already cached
    if (!isset($_builtin_state['parentClasses'][$className])) goto store_parents;
    goto skip_parents;

    store_parents:
    $rc = new ReflectionClass($className); // @phpstan-ignore spaghetti.noNew
    $parents = [];
    $current = $rc;

    parent_loop:
    $parent = $current->getParentClass(); // @phpstan-ignore spaghetti.noMethodCall
    $hasNoParent = $parent === false;
    if ($hasNoParent) goto parent_done;
    $parentName = $parent->getName(); // @phpstan-ignore spaghetti.noMethodCall
    $parents[] = $parentName;
    $current = $parent;
    goto parent_loop;

    parent_done:
    // Also add all interfaces (direct and inherited)
    $interfaces = $rc->getInterfaceNames(); // @phpstan-ignore spaghetti.noMethodCall
    $interfaceCount = count($interfaces);
    $interfaceIndex = 0;

    interface_loop:
    $hasMoreInterfaces = $interfaceIndex < $interfaceCount;
    if (!$hasMoreInterfaces) goto interface_done;
    $interfaceName = $interfaces[$interfaceIndex];
    $parents[] = $interfaceName;
    $interfaceIndex++;
    goto interface_loop;

    interface_done:
    $_builtin_state['parentClasses'][$className] = $parents;

    skip_parents:
    $result = $newId;

    return_result:
    return $result; // @phpstan-ignore spaghetti.noReturn
}

/**
 * Create a new builtin class instance.
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_new($class, $args = [])
{
    global $_builtin_state;

    $_builtin_state['idCounter']++;
    $id = $_builtin_state['idCounter'] | (1 << _BUILTIN_TAG_BIT);

    $rc = new ReflectionClass($class); // @phpstan-ignore spaghetti.noNew

    // Unwrap builtin spaghetti object IDs to real PHP objects before construction.
    // Builtin IDs are tagged integers (bit _BUILTIN_TAG_BIT set). This allows
    // passing builtin objects (e.g. a PSR-7 Request) to other builtin constructors.
    $unwrappedArgs = [];
    $_bna_i = 0;
    $_bna_count = count($args);

    unwrap_args_loop:
    $_bna_done = $_bna_i >= $_bna_count;
    if ($_bna_done) goto unwrap_args_done;
    $_bna = $args[$_bna_i];
    $_bna_is_builtin = is_int($_bna) && ($_bna & (1 << _BUILTIN_TAG_BIT)) !== 0;
    if (!$_bna_is_builtin) goto unwrap_args_plain;
    $_bna_unwrapped = $_bna;
    if (!isset($_builtin_state['objects'][$_bna])) goto unwrap_args_store;
    $_bna_unwrapped = $_builtin_state['objects'][$_bna];
    goto unwrap_args_store;

    unwrap_args_plain:
    $_bna_unwrapped = $_bna;

    unwrap_args_store:
    $unwrappedArgs[] = $_bna_unwrapped;
    $_bna_i++;
    goto unwrap_args_loop;

    unwrap_args_done:

    try { // @phpstan-ignore spaghetti.noTryCatch
        $hasConstructor = $rc->getConstructor() !== null; // @phpstan-ignore spaghetti.noMethodCall
        $hasArgs = $unwrappedArgs !== [];

        if (!$hasConstructor) goto no_constructor;
        if (!$hasArgs) goto constructor_no_args;
        $obj = $rc->newInstanceArgs($unwrappedArgs); // @phpstan-ignore spaghetti.noMethodCall
        goto constructor_done;

        constructor_no_args:
        $obj = $rc->newInstance(); // @phpstan-ignore spaghetti.noMethodCall
        goto constructor_done;

        no_constructor:
        $obj = $rc->newInstanceWithoutConstructor(); // @phpstan-ignore spaghetti.noMethodCall

        constructor_done:
    } catch (ReflectionException $e) {
        $obj = $rc->newInstance(); // @phpstan-ignore spaghetti.noMethodCall
    }

    $_builtin_state['objects'][$id] = $obj;
    $_builtin_state['objectMap'][spl_object_id($obj)] = $id;

    // Store class name for instanceof checks
    $_builtin_state['classNames'][$id] = $class;

    // Store parent classes and interfaces if not already cached
    if (!isset($_builtin_state['parentClasses'][$class])) goto store_parents;
    goto skip_parents;

    store_parents:
    $parents = [];
    $current = $rc;

    parent_loop:
    $parent = $current->getParentClass(); // @phpstan-ignore spaghetti.noMethodCall
    $hasNoParent = $parent === false;
    if ($hasNoParent) goto parent_done;
    $parentName = $parent->getName(); // @phpstan-ignore spaghetti.noMethodCall
    $parents[] = $parentName;
    $current = $parent;
    goto parent_loop;

    parent_done:
    // Also add all interfaces (direct and inherited)
    $interfaces = $rc->getInterfaceNames(); // @phpstan-ignore spaghetti.noMethodCall
    $interfaceCount = count($interfaces);
    $interfaceIndex = 0;

    interface_loop:
    $hasMoreInterfaces = $interfaceIndex < $interfaceCount;
    if (!$hasMoreInterfaces) goto interface_done;
    $interfaceName = $interfaces[$interfaceIndex];
    $parents[] = $interfaceName;
    $interfaceIndex++;
    goto interface_loop;

    interface_done:
    $_builtin_state['parentClasses'][$class] = $parents;

    skip_parents:
    return $id; // @phpstan-ignore spaghetti.noReturn
}

/**
 * Call an instance method on a builtin object.
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_call($id, $method, $args = [])
{
    global $_builtin_state;

    if (!isset($_builtin_state['objects'][$id])) goto invalid_id;

    $obj = $_builtin_state['objects'][$id];

    // Unwrap builtin object IDs in arguments
    $unwrapped = [];
    $i = 0;
    $count = count($args);

    unwrap_loop:
    $done = $i >= $count;
    if ($done) goto unwrap_done;
    $unwrapped[] = __builtin_unwrap($args[$i]);
    $i++;
    goto unwrap_loop;

    unwrap_done:
    $result = $obj->$method(...$unwrapped); // @phpstan-ignore spaghetti.noMethodCall

    return __builtin_register_if_object($result); // @phpstan-ignore spaghetti.noReturn

    invalid_id:
    trigger_error("Invalid FFI object ID: {$id}", E_USER_ERROR);
}

/**
 * Call a static method on a builtin class.
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_static_call($class, $method, $args = [])
{
    // Unwrap builtin object IDs in arguments
    $unwrapped = [];
    $i = 0;
    $count = count($args);

    unwrap_loop:
    $done = $i >= $count;
    if ($done) goto unwrap_done;
    $unwrapped[] = __builtin_unwrap($args[$i]);
    $i++;
    goto unwrap_loop;

    unwrap_done:
    $result = $class::$method(...$unwrapped); // @phpstan-ignore spaghetti.noStaticCall

    return __builtin_register_if_object($result); // @phpstan-ignore spaghetti.noReturn
}

/**
 * Unwrap an builtin object ID to the actual object, or return the value as-is.
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_unwrap($idOrValue)
{
    global $_builtin_state;

    $is_ffi_id = is_int($idOrValue) && $idOrValue > 0 && (($idOrValue >> _BUILTIN_TAG_BIT) & 1) === 1;
    if (!$is_ffi_id) goto return_value;

    assert(is_int($idOrValue));

    if (!isset($_builtin_state['objects'][$idOrValue])) goto invalid_id;

    $idOrValue = $_builtin_state['objects'][$idOrValue];

    return_value:
    return $idOrValue; // @phpstan-ignore spaghetti.noReturn

    invalid_id:
    trigger_error("Invalid FFI object ID in unwrap: {$idOrValue}", E_USER_ERROR);
}

/**
 * Clone a builtin object and return a new ID pointing to the cloned object.
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_clone($id)
{
    global $_builtin_state;

    if (!isset($_builtin_state['objects'][$id])) goto invalid_id;

    $obj = $_builtin_state['objects'][$id];
    $cloned = clone $obj;

    $_builtin_state['idCounter']++;
    $newId = $_builtin_state['idCounter'] | (1 << _BUILTIN_TAG_BIT);
    $_builtin_state['objects'][$newId] = $cloned;
    $_builtin_state['objectMap'][spl_object_id($cloned)] = $newId;

    $class = '';
    if (isset($_builtin_state['classNames'][$id])) goto has_class;
    goto skip_class;
    has_class: $class = $_builtin_state['classNames'][$id];
    skip_class:
    $_builtin_state['classNames'][$newId] = $class;

    return $newId; // @phpstan-ignore spaghetti.noReturn

    invalid_id:
    trigger_error("Invalid FFI object ID in clone: {$id}", E_USER_ERROR);
}

/**
 * Define a PHP class at runtime using eval().
 * Used for builtin-extending user classes (e.g., class MyException extends Exception).
 *
 * @param string $sourceCode PHP source code defining the class
 * @param string $className Fully-qualified class name
 */
// @phpstan-ignore spaghetti.noFunction
function __builtin_define_class($sourceCode, $className)
{
    $already = class_exists($className, false) || interface_exists($className, false); // @phpstan-ignore spaghetti.noTypeCheckFunction
    if ($already) goto skip;

    try { // @phpstan-ignore spaghetti.noTryCatch
        eval($sourceCode);
    } catch (\Throwable $e) {
        trigger_error("Failed to define class {$className}: " . $e->getMessage(), E_USER_ERROR); // @phpstan-ignore spaghetti.noMethodCall
    }

    skip:
}

